# Refresh product hub by scanning pages (existing + wave2)
def title_of(path):
    s=path.read_text(encoding='utf-8', errors='ignore')
    h=re.search(r'<h1[^>]*>(.*?)</h1>',s,re.I|re.S)
    if h: return re.sub(r'<[^>]+>','',h.group(1)).strip()
    t=re.search(r'<title[^>]*>(.*?)</title>',s,re.I|re.S)
    return re.sub(r'<[^>]+>','',t.group(1)).strip() if t else path.stem

def desc_of(path):
    s=path.read_text(encoding='utf-8', errors='ignore')
    m=re.search(r'<meta\s+[^>]*name=["\']description["\'][^>]*content=["\']([^"\']+)',s,re.I|re.S)
    return m.group(1).strip() if m else ''

cards=[]
for f in sorted(OUT.glob('*.html')):
    if f.name=='index.html': continue
    cards.append(f'<a class="ptf-card" href="{f.name}"><b>{escape(title_of(f))}</b><small>{escape(desc_of(f)[:150])}</small></a>')
